SELECT s.subject, s.id, s.ref, s.status, s.status_category, s.assignee, s.priority, s.resolution, s.issue_type, s.in_project
FROM issue_state_known_at('spring', TIMESTAMP '2016-01-27 10:38', k := now()) s
WHERE s.ref = 'SEC-3147' OR s.id = 'SEC-3147';

SELECT subject, id, ref, status, status_category, resolution
FROM issue_state_at('hyperledger', TIMESTAMP '2020-11-24 05:35')
WHERE ref = 'INDY-1717' OR id = 'INDY-1717';

SELECT subject, ref, status, status_category, resolution
FROM issue_state_at('hyperledger', TIMESTAMP '2020-11-24 05:35')
WHERE subject IN ('issue:INDY-1343','issue:INDY-1638','issue:INDY-1607','issue:INDY-1737','issue:INDY-2214');

SELECT subject, id, ref, status, status_category, resolution
FROM issue_state_known_at('hyperledger', TIMESTAMP '2019-12-29 15:28', k := TIMESTAMP '2019-12-29 15:28')
WHERE ref = 'INDY-1022' OR id = 'INDY-1022';
